package cn.edu.travel;

import java.util.*;
import java.nio.file.*;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.imageio.*;
import javax.imageio.stream.ImageInputStream;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.core.io.FileSystemResource;
import org.springframework.http.*;
import static cn.edu.travel.ApiController.*;

/** 路线收藏与私人逐站回忆；足迹照片通过本人接口读取，不映射到公开上传目录。 */
@RestController
@RequestMapping("/api")
public class DepthController {
    final Database db;final Auth auth;
    public DepthController(Database db,Auth auth){this.db=db;this.auth=auth;}
    Map<String,Object> ownMemory(long id,HttpServletRequest req){var u=auth.require(req);return db.one("SELECT m.*,t.user_id FROM travel_memories m JOIN trips t ON t.id=m.trip_id WHERE m.trip_id=? AND t.user_id=?",id,u.get("id"));}
    void publicRoute(long id){db.one("SELECT id FROM shared_routes WHERE id=? AND status='PUBLISHED' AND blocked=0",id);}
    @GetMapping("/routes/{id}/favorite") Object favorite(@PathVariable long id,HttpServletRequest req){publicRoute(id);var u=auth.current(req);return Map.of("favorited",u!=null&&db.count("SELECT count(*) FROM route_favorites WHERE user_id=? AND route_id=?",u.get("id"),id)>0,"favorite_count",db.count("SELECT count(*) FROM route_favorites WHERE route_id=?",id));}
    @PutMapping("/routes/{id}/favorite") Object addFavorite(@PathVariable long id,HttpServletRequest req){var u=auth.require(req);return db.transaction(status->{publicRoute(id);if(db.count("SELECT count(*) FROM route_favorites WHERE user_id=?",u.get("id"))>=200&&db.count("SELECT count(*) FROM route_favorites WHERE user_id=? AND route_id=?",u.get("id"),id)==0)throw new ApiError(400,"最多收藏 200 条路线，请先整理");db.update("INSERT OR IGNORE INTO route_favorites(user_id,route_id) VALUES(?,?)",u.get("id"),id);return Map.of("message","路线已收藏","favorited",true);});}
    @DeleteMapping("/routes/{id}/favorite") Object removeFavorite(@PathVariable long id,HttpServletRequest req){var u=auth.require(req);db.update("DELETE FROM route_favorites WHERE user_id=? AND route_id=?",u.get("id"),id);return Map.of("message","已取消路线收藏","favorited",false);}
    @GetMapping("/me/route-favorites") Object favorites(HttpServletRequest req){var u=auth.require(req);var rows=db.list("SELECT r.id,CASE WHEN r.status='PUBLISHED' AND r.blocked=0 THEN r.title ELSE '暂不可用的路线' END AS title,CASE WHEN r.status='PUBLISHED' AND r.blocked=0 THEN r.description ELSE '' END AS description,r.days,CASE WHEN r.status='PUBLISHED' AND r.blocked=0 THEN 1 ELSE 0 END AS available,f.created_at FROM route_favorites f JOIN shared_routes r ON r.id=f.route_id WHERE f.user_id=? ORDER BY f.created_at DESC,r.id DESC",u.get("id"));return rows;}
    @SuppressWarnings("unchecked") List<Map<String,Object>> snapshotItems(Map<String,Object> m){Object decoded=db.decode(m.get("snapshot"));if(decoded instanceof Map<?,?> snapshot&&snapshot.get("items") instanceof List<?> list)return (List<Map<String,Object>>)(List<?>)list;throw new ApiError(400,"这份回忆的景点快照无法读取");}
    @GetMapping("/me/trips/{id}/memory-details") Object details(@PathVariable long id,HttpServletRequest req){var m=ownMemory(id,req);var rows=db.list("SELECT entries,revision FROM memory_details WHERE trip_id=?",id);return Map.of("trip_id",id,"items",snapshotItems(m),"entries",rows.isEmpty()?List.of():db.decode(rows.get(0).get("entries")),"revision",rows.isEmpty()?0:rows.get(0).get("revision"),"note",m.get("note"));}
    @PutMapping("/me/trips/{id}/memory-details") Object saveDetails(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){return db.transaction(status->{var m=ownMemory(id,req);Set<Long> ids=new HashSet<>();for(var item:snapshotItems(m))ids.add(number(item.get("spot_id")));if(!(b.get("entries") instanceof List<?> entries)||entries.size()>80)throw new ApiError(400,"逐站回忆格式不正确");Set<Long> seen=new HashSet<>();List<Map<String,Object>> clean=new ArrayList<>();for(Object raw:entries){if(!(raw instanceof Map<?,?> item))throw new ApiError(400,"逐站回忆格式不正确");long spot=number(item.get("spot_id"));if(!ids.contains(spot)||!seen.add(spot))throw new ApiError(400,"请选择足迹快照中不重复的景点");String note=Objects.toString(item.get("note"),"").trim(),image=Objects.toString(item.get("image"),"");if(note.length()>500)throw new ApiError(400,"每站感想最多 500 字");if(!image.isEmpty()){String prefix="/api/me/trips/"+id+"/memory-details/photos/";if(!image.startsWith(prefix))throw new ApiError(400,"请选择这份回忆中上传的照片");String key=image.substring(prefix.length());if(!key.matches("[0-9a-f-]{36}\\.jpg")||db.count("SELECT count(*) FROM memory_photos WHERE trip_id=? AND photo_key=?",id,key)==0)throw new ApiError(400,"照片不属于这份回忆");}clean.add(Map.of("spot_id",spot,"note",note,"image",image));}long revision=number(b.getOrDefault("revision",0));int changed=revision==0?db.update("INSERT OR IGNORE INTO memory_details(trip_id,entries) VALUES(?,?)",id,db.encode(clean)):db.update("UPDATE memory_details SET entries=?,revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE trip_id=? AND revision=?",db.encode(clean),id,revision);if(changed==0)throw new ApiError(409,"逐站回忆已更新，请刷新后再保存");return Map.of("message","逐站回忆已保存");});}
    @PostMapping("/me/trips/{id}/memory-details/photos") Object upload(@PathVariable long id,@RequestParam("file") MultipartFile file,HttpServletRequest req) throws Exception {ownMemory(id,req);if(file.isEmpty()||file.getSize()>5*1024*1024)throw new ApiError(400,"请选择 5 MB 以内的 JPG 或 PNG 图片");if(db.count("SELECT count(*) FROM memory_photos WHERE trip_id=?",id)>=80)throw new ApiError(400,"每份回忆最多上传 80 张照片");BufferedImage original;try(ImageInputStream stream=ImageIO.createImageInputStream(file.getInputStream())){var readers=ImageIO.getImageReaders(stream);if(!readers.hasNext())throw new ApiError(400,"图片无法读取，请使用 JPG 或 PNG");ImageReader reader=readers.next();try{if(!Set.of("JPEG","PNG").contains(reader.getFormatName().toUpperCase(Locale.ROOT)))throw new ApiError(400,"只支持 JPG 或 PNG 图片");reader.setInput(stream);int w=reader.getWidth(0),h=reader.getHeight(0);if(w<1||h<1||(long)w*h>30_000_000L||w>15000||h>15000)throw new ApiError(400,"图片尺寸过大，请缩小后上传");original=reader.read(0);}finally{reader.dispose();}}catch(java.io.IOException e){throw new ApiError(400,"图片文件不完整或无法读取");}double scale=Math.min(1,1600.0/Math.max(original.getWidth(),original.getHeight()));int w=Math.max(1,(int)(original.getWidth()*scale)),h=Math.max(1,(int)(original.getHeight()*scale));BufferedImage image=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,w,h);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);g.drawImage(original,0,0,w,h,null);g.dispose();String key=UUID.randomUUID()+".jpg";Path dir=TravelApplication.DATA.resolve("private-memories").resolve(String.valueOf(id));Files.createDirectories(dir);Path path=dir.resolve(key);ImageIO.write(image,"jpg",path.toFile());try{db.transaction(status->{ownMemory(id,req);if(db.count("SELECT count(*) FROM memory_photos WHERE trip_id=?",id)>=80)throw new ApiError(400,"每份回忆最多上传 80 张照片");db.update("INSERT INTO memory_photos(trip_id,photo_key) VALUES(?,?)",id,key);return null;});}catch(RuntimeException e){Files.deleteIfExists(path);throw e;}return Map.of("url","/api/me/trips/"+id+"/memory-details/photos/"+key);}
    @GetMapping("/me/trips/{id}/memory-details/photos/{key}") ResponseEntity<FileSystemResource> photo(@PathVariable long id,@PathVariable String key,HttpServletRequest req){ownMemory(id,req);if(!key.matches("[0-9a-f-]{36}\\.jpg"))throw new ApiError(404,"没有找到照片");db.one("SELECT photo_key FROM memory_photos WHERE trip_id=? AND photo_key=?",id,key);Path path=TravelApplication.DATA.resolve("private-memories").resolve(String.valueOf(id)).resolve(key);if(!Files.isRegularFile(path))throw new ApiError(404,"没有找到照片");return ResponseEntity.ok().contentType(MediaType.IMAGE_JPEG).cacheControl(CacheControl.noStore()).body(new FileSystemResource(path));}
    @PostMapping("/me/trips/{id}/memory-details/draft") Object draft(@PathVariable long id,@RequestBody Map<String,Object> b,HttpServletRequest req){var m=ownMemory(id,req);if(!(b.get("spot_ids") instanceof List<?> raw)||raw.size()>80)throw new ApiError(400,"请选择想分享的景点");Set<Long> selected=new HashSet<>();for(Object value:raw)selected.add(number(value));var items=snapshotItems(m);Set<Long> known=new HashSet<>();for(var s:items)known.add(number(s.get("spot_id")));if(!known.containsAll(selected))throw new ApiError(400,"只能选择这份足迹中的景点");var detailRows=db.list("SELECT entries FROM memory_details WHERE trip_id=?",id);Map<Long,String> notes=new HashMap<>();if(!detailRows.isEmpty()&&db.decode(detailRows.get(0).get("entries")) instanceof List<?> list)for(Object value:list)if(value instanceof Map<?,?> entry)notes.put(number(entry.get("spot_id")),Objects.toString(entry.get("note"),""));StringBuilder body=new StringBuilder();if(Boolean.TRUE.equals(b.get("include_note"))&&!Objects.toString(m.get("note"),"").isBlank())body.append(m.get("note")).append("\n\n");long city=0;boolean multi=false;for(var s:items)if(selected.contains(number(s.get("spot_id")))){long c=number(s.get("city_id"));if(city==0)city=c;else if(city!=c)multi=true;body.append("第 ").append(s.get("day_number")).append(" 天 · ").append(s.get("title")).append("\n");String note=notes.getOrDefault(number(s.get("spot_id")),"");body.append(note.isBlank()?"在这里补充这一站的经历和感想。":note).append("\n\n");}if(selected.isEmpty()&&body.isEmpty())throw new ApiError(400,"请至少选择一站或包含整体感想");Object decoded=db.decode(m.get("snapshot"));String title=decoded instanceof Map<?,?> sm?Objects.toString(sm.get("title"),"我的旅行回忆"):"我的旅行回忆";if(title.length()>74)title=title.substring(0,74);String content=body.toString().trim();if(content.length()>12000)throw new ApiError(400,"选中的感想超过 12000 字，请减少分享的站点");return Map.of("title",title+" · 游记","body",content,"category","游记","city_id",multi?0:city,"image","");}
    @GetMapping("/admin/completeness") Object completeness(HttpServletRequest req){auth.admin(req);List<Map<String,Object>> out=new ArrayList<>();int total=0;for(String kind:List.of("spots","guides","foods","cities")){for(var row:db.list("SELECT * FROM "+kind)){total++;List<String> missing=new ArrayList<>();if(blank(row,"image"))missing.add(kind.equals("foods")?"未配实景图（可保留文字版）":"缺封面图片");if((kind.equals("spots")||kind.equals("guides"))&&number(row.get("duration_minutes"))<=0)missing.add("缺建议时长");if(!kind.equals("cities")&&blank(row,"source_url"))missing.add("缺资料来源");if(kind.equals("spots")){if(blank(row,"transportation"))missing.add("缺交通建议");if(blank(row,"tips"))missing.add("缺游览提示");}if(kind.equals("guides")){if(!(db.decode(row.get("sections")) instanceof List<?> list)||list.isEmpty())missing.add("缺攻略正文");if(db.count("SELECT count(*) FROM guide_spots WHERE guide_id=?",row.get("id"))==0)missing.add("未关联景点");}if(kind.equals("foods")&&blank(row,"tips"))missing.add("缺用餐建议");if(kind.equals("cities")){if(blank(row,"travel_advice"))missing.add("缺出行建议");if(blank(row,"visit_advice"))missing.add("缺游玩节奏");if(blank(row,"food_source"))missing.add("缺食味资料来源");}if(!missing.isEmpty())out.add(Map.of("kind",kind,"id",row.get("id"),"title",Objects.toString(row.get(kind.equals("cities")?"name":"title"),""),"missing",missing,"published",row.getOrDefault("published",1)));}}return Map.of("total",total,"needs_attention",out.size(),"items",out);}
    boolean blank(Map<String,Object> row,String key){return Objects.toString(row.get(key),"").isBlank();}
}
